contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    // run accepts an amount to forward when calling c.go
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        // observe owner and c balance before the call
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint balanceBefore = address(c).balance;
        // attempt the call and record whether it reverted
        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        // observe owner and c balance after the call
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint balanceAfter = address(c).balance;
        // If the call did not revert, owner must be unchanged and c's balance must be zero (all funds forwarded out)
        // If it reverted, we cannot assume balance moved, but owner must still remain unchanged (constructor set owner immutable publicly)
        assert(ownerBefore == ownerAfter && (reverted || balanceAfter == 0));
    }
    receive() external payable {}
}

